package org.example;


import java.util.*;

public class App {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        System.out.println("======================================");
        System.out.println(" ЛАБОРАТОРНАЯ РАБОТА №2");
        System.out.println(" Минимизация конечного автомата");
        System.out.println("======================================");

        System.out.println("1. Проверить пример из лекции");
        System.out.println("2. Ввести собственный автомат");

        System.out.print("\nВыберите вариант: ");

        int choice = Integer.parseInt(scanner.nextLine().trim());

        Automaton automaton;

        if (choice == 1) {

            automaton = createLectureExample();

            System.out.println("\nИспользуется пример из лекции.");

        } else if (choice == 2) {

            automaton = readAutomaton(scanner);

        } else {

            System.out.println("Неверный выбор.");
            return;
        }

        // Вывод исходного автомата.
        System.out.println("\n======================================");
        System.out.println("ИСХОДНЫЙ АВТОМАТ");
        System.out.println("======================================");

        automaton.print();

        GraphPrinter.printGraph(
                automaton,
                "Исходный НКА"
        );
        // Проверка детерминированности.
        System.out.println("\n======================================");
        System.out.println("ПРОВЕРКА ДЕТЕРМИНИРОВАННОСТИ");
        System.out.println("======================================");

        boolean deterministic = automaton.isDeterministic();

        if (deterministic) {

            System.out.println(
                    "Автомат является детерминированным (ДКА)."
            );

        } else {

            System.out.println(
                    "Автомат является недетерминированным (НКА)."
            );
        }

        // Детерминизация при необходимости.
        Automaton dfa;

        if (deterministic) {

            System.out.println(
                    "\nДетерминизация не требуется."
            );

            dfa = automaton;

        } else {

            System.out.println(
                    "\nВыполняется преобразование НКА в ДКА..."
            );

            dfa = Determinizer.determinize(automaton);
        }

        // Вывод ДКА.
        System.out.println("\n======================================");
        System.out.println("ДЕТЕРМИНИРОВАННЫЙ АВТОМАТ");
        System.out.println("======================================");

        dfa.print();

        GraphPrinter.printGraph(
                dfa,
                "ДКА перед минимизацией"
        );

        // Минимизация.
        Automaton minimized = Minimizer.minimize(dfa);

        // Итоговый результат.
        System.out.println("\n======================================");
        System.out.println("МИНИМИЗИРОВАННЫЙ ДКА");
        System.out.println("======================================");

        minimized.print();

        GraphPrinter.printGraph(
                minimized,
                "Минимизированный ДКА"
        );

        System.out.println("\n======================================");
        System.out.println("РЕЗУЛЬТАТ РАБОТЫ");
        System.out.println("======================================");

        System.out.println(
                "Исходное количество состояний: "
                        + automaton.getStates().size()
        );

        System.out.println(
                "Количество состояний ДКА: "
                        + dfa.getStates().size()
        );

        System.out.println(
                "Количество состояний минимального ДКА: "
                        + minimized.getStates().size()
        );

        System.out.println(
                "Итоговый автомат детерминирован: "
                        + minimized.isDeterministic()
        );

        System.out.println("\nРабота программы завершена.");
    }

    /**
     * НКА из лекции:
     *
     * M = ({p, q, r}, {0, 1}, δ, p, {r})
     *
     *       0       1
     * p    {p}     {p,q}
     * q     ∅       {r}
     * r     ∅        ∅
     *
     * Распознаваемый язык: (0+1)*11
     */
    static Automaton createLectureExample() {

        Set<String> states = new LinkedHashSet<>(
                Arrays.asList("p", "q", "r")
        );

        Set<String> alphabet = new LinkedHashSet<>(
                Arrays.asList("0", "1")
        );

        String initialState = "p";

        Set<String> finalStates = new LinkedHashSet<>(
                Collections.singletonList("r")
        );

        Map<String, Map<String, Set<String>>> transitions =
                new LinkedHashMap<>();

        transitions.put("p", new LinkedHashMap<>());
        transitions.put("q", new LinkedHashMap<>());
        transitions.put("r", new LinkedHashMap<>());

        // Состояние p
        transitions.get("p").put("0",
                new LinkedHashSet<>(Arrays.asList("p")));

        transitions.get("p").put("1",
                new LinkedHashSet<>(Arrays.asList("p", "q")));

        // В лекционном НКА из q есть только переход по 1 в r.
        transitions.get("q").put("1", Set.of("r"));

        return new Automaton(
                states,
                alphabet,
                initialState,
                finalStates,
                transitions
        );
    }

    /**
     * Ручной ввод автомата.
     */
    private static Automaton readAutomaton(Scanner scanner) {

        System.out.println("\n=== ВВОД АВТОМАТА ===");

        System.out.println(
                "Вводите значения через запятую."
        );

        System.out.print("Множество состояний Q: ");

        Set<String> states = readSet(scanner.nextLine());

        System.out.print("Алфавит Σ: ");

        Set<String> alphabet = readSet(scanner.nextLine());

        System.out.print("Начальное состояние: ");

        String initialState = scanner.nextLine().trim();

        System.out.print("Конечные состояния F (или -): ");

        Set<String> finalStates = readSet(scanner.nextLine());

        Map<String, Map<String, Set<String>>> transitions =
                new LinkedHashMap<>();

        System.out.println(
                "\n=== ВВОД ТАБЛИЦЫ ПЕРЕХОДОВ ==="
        );

        System.out.println(
                "Для каждой пары состояние-символ укажите"
        );

        System.out.println(
                "множество целевых состояний через запятую."
        );

        System.out.println(
                "Если переход отсутствует, введите -."
        );

        for (String state : states) {

            Map<String, Set<String>> stateTransitions =
                    new LinkedHashMap<>();

            for (String symbol : alphabet) {

                System.out.print(
                        "δ(" + state + ", " + symbol + ") = "
                );

                Set<String> destinations =
                        readSet(scanner.nextLine());

                stateTransitions.put(symbol, destinations);
            }

            transitions.put(state, stateTransitions);
        }

        return new Automaton(
                states,
                alphabet,
                initialState,
                finalStates,
                transitions
        );
    }

    /**
     * Преобразование строки в множество.
     */
    private static Set<String> readSet(String input) {

        Set<String> result = new LinkedHashSet<>();

        input = input.trim();

        if (input.isEmpty() || input.equals("-")) {
            return result;
        }

        for (String value : input.split(",")) {

            String element = value.trim();

            if (!element.isEmpty()) {
                result.add(element);
            }
        }

        return result;
    }
}
